// cfgNum reads a numeric parameter, falling back to def on any misshape so a
// sloppy configuration degrades the signal, never the process.
func closes(cs []candle) []float64 {
	out := make([]float64, 0, len(cs))
	for _, c := range cs {
		f, err := strconv.ParseFloat(c.Close, 64)
		if err != nil {
			return nil
		}
		out = append(out, f)
	}
	return out
}

func cfgNum(cfg map[string]any, key string, def float64) float64 {
	v, ok := cfg[key]
	if !ok {
		return def
	}
	switch n := v.(type) {
	case float64:
		if n > 0 {
			return n
		}
	case string:
		if f, err := strconv.ParseFloat(n, 64); err == nil && f > 0 {
			return f
		}
	}
	return def
}

// cfgFloat reads a numeric parameter that may legitimately be zero or
// negative (tolerances, thresholds); misshaped values fall back to def so a
// sloppy configuration degrades the signal, never the process.
func cfgFloat(cfg map[string]any, key string, def float64) float64 {
	v, ok := cfg[key]
	if !ok {
		return def
	}
	switch n := v.(type) {
	case float64:
		if !math.IsNaN(n) {
			return n
		}
	case string:
		if f, err := strconv.ParseFloat(n, 64); err == nil && !math.IsNaN(f) {
			return f
		}
	}
	return def
}

// obar is one parsed OHLC bar; opens are needed for candle direction.
type obar struct {
	o, h, l, c float64
}

// obars parses candle decimal strings; any misshape fails the series.
func obars(cs []candle) ([]obar, bool) {
	out := make([]obar, 0, len(cs))
	for _, cn := range cs {
		o, e1 := strconv.ParseFloat(cn.Open, 64)
		h, e2 := strconv.ParseFloat(cn.High, 64)
		l, e3 := strconv.ParseFloat(cn.Low, 64)
		x, e4 := strconv.ParseFloat(cn.Close, 64)
		if e1 != nil || e2 != nil || e3 != nil || e4 != nil {
			return nil, false
		}
		out = append(out, obar{o: o, h: h, l: l, c: x})
	}
	return out, true
}

// atrLast is the mean true range of the final n bars (indicator math only;
// policy decisions never use float64 prices for identity).
func atrLast(bs []obar, n int) float64 {
	if n <= 0 || len(bs) < n+1 {
		return 0
	}
	tail := bs[len(bs)-n-1:]
	sum := 0.0
	for i := 1; i < len(tail); i++ {
		h, l, pc := tail[i].h, tail[i].l, tail[i-1].c
		tr := h - l
		if d := h - pc; d > tr {
			tr = d
		}
		if d := pc - l; d > tr {
			tr = d
		}
		sum += tr
	}
	return sum / float64(n)
}

// avgBodyLast is the mean |close-open| of the final n bars.
func avgBodyLast(bs []obar, n int) float64 {
	if n <= 0 || len(bs) < n {
		return 0
	}
	tail := bs[len(bs)-n:]
	sum := 0.0
	for _, b := range tail {
		d := b.c - b.o
		if d < 0 {
			d = -d
		}
		sum += d
	}
	return sum / float64(n)
}

// decide implements the order-block (supply/demand) entry: the last
// opposite-colour candle before a displacement leg is the block, and a
// return of price into that block is the trigger — LONG on a bullish
// (demand) block, SHORT on a bearish (supply) block. No displacement,
// no block, or no retest is FLAT — an analytical unknown, never a crash.
func decide(inv invocation) (bias string, conf float64, logs []string) {
	cfg := inv.StrategyConfiguration
	if cfg == nil {
		cfg = map[string]any{}
	}
	atrN := int(cfgNum(cfg, "atr_period", 14))
	if atrN < 2 {
		atrN = 2
	}
	if atrN > 50 {
		atrN = 50
	}
	lookback := int(cfgNum(cfg, "lookback", 50))
	if lookback < 10 {
		lookback = 10
	}
	if lookback > 200 {
		lookback = 200
	}
	bodyMult := cfgFloat(cfg, "body_mult", 1.5)
	if math.IsNaN(bodyMult) || bodyMult <= 0 {
		bodyMult = 1.5
	}
	atrMult := cfgFloat(cfg, "displacement_atr_mult", 1.0)
	if math.IsNaN(atrMult) || atrMult <= 0 {
		atrMult = 1.0
	}
	tolMult := cfgFloat(cfg, "retest_tol_atr", 0.15)
	if math.IsNaN(tolMult) || tolMult < 0 {
		tolMult = 0.15
	}
	maxAge := int(cfgNum(cfg, "max_age_bars", 30))
	if maxAge < 1 {
		maxAge = 30
	}
	minConf := cfgNum(cfg, "min_confidence", 0.55)
	if minConf <= 0 || minConf > 1 {
		minConf = 0.55
	}
	signalConf := cfgFloat(cfg, "signal_confidence", 0.6)
	if math.IsNaN(signalConf) || signalConf <= 0 || signalConf > 1 {
		signalConf = 0.6
	}

	cs := inv.MarketSnapshot.Candles
	need := atrN + 6
	if len(cs) < need {
		return "FLAT", 0.0, []string{fmt.Sprintf("need %d candles, have %d", need, len(cs))}
	}
	bs, ok := obars(cs)
	if !ok {
		return "FLAT", 0.0, []string{"unparsable candle series"}
	}
	atr := atrLast(bs, atrN)
	avgBody := avgBodyLast(bs, atrN)
	if atr <= 0 || avgBody <= 0 {
		return "FLAT", 0.0, []string{"flat market — no measurable range"}
	}

	// Last displacement inside the lookback: a body at least bodyMult
	// times the average body AND a range at least atrMult times ATR.
	n := len(bs)
	from := n - lookback
	if from < 1 {
		from = 1
	}
	dispIdx, dispDir := -1, ""
	for i := from; i < n; i++ {
		body := bs[i].c - bs[i].o
		rng := bs[i].h - bs[i].l
		if rng < atrMult*atr {
			continue
		}
		if body >= bodyMult*avgBody {
			dispIdx, dispDir = i, "bull"
		} else if -body >= bodyMult*avgBody {
			dispIdx, dispDir = i, "bear"
		}
	}
	if dispIdx < 0 {
		return "FLAT", 0.0, []string{"no displacement leg in lookback"}
	}
	if n-1-dispIdx > maxAge {
		return "FLAT", 0.0, []string{"displacement too old — block stale"}
	}

	// The block is the nearest opposite-colour candle before the leg.
	zLo, zHi, found := 0.0, 0.0, false
	for i := dispIdx - 1; i >= dispIdx-6 && i >= 0; i-- {
		bull := bs[i].c > bs[i].o
		bear := bs[i].o > bs[i].c
		if (dispDir == "bull" && bear) || (dispDir == "bear" && bull) {
			zLo, zHi, found = bs[i].l, bs[i].h, true
			break
		}
	}
	if !found {
		return "FLAT", 0.0, []string{"no order block before displacement"}
	}

	tol := tolMult * atr
	last := bs[n-1].c
	if last < zLo-tol || last > zHi+tol {
		return "FLAT", 0.0, []string{"price outside the block — awaiting retest"}
	}
	if minConf > signalConf {
		return "FLAT", 0.0, []string{"block retest but below min_confidence gate"}
	}
	if dispDir == "bull" {
		return "LONG", signalConf, []string{"retest of bullish order block (demand)"}
	}
	return "SHORT", signalConf, []string{"retest of bearish order block (supply)"}
}

